using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Settings.Units;public class IndexModel(ApplicationDbContext db,IPermissionService permissions):PageModel
{
 public IReadOnlyList<UnitOfMeasure> Items{get;private set;}=[];[BindProperty(SupportsGet=true)]public string? Search{get;set;}[BindProperty(SupportsGet=true)]public int PageNumber{get;set;}=1;public int TotalPages{get;private set;}public bool CanAdd{get;private set;}public bool CanUpdate{get;private set;}public bool CanDelete{get;private set;}
 public async Task OnGetAsync(){const int size=15;var q=db.Units.AsNoTracking();if(!string.IsNullOrWhiteSpace(Search))q=q.Where(x=>x.Name.Contains(Search)||(x.Comments!=null&&x.Comments.Contains(Search)));var count=await q.CountAsync();TotalPages=Math.Max(1,(int)Math.Ceiling(count/(double)size));PageNumber=Math.Clamp(PageNumber,1,TotalPages);Items=await q.OrderBy(x=>x.Name).Skip((PageNumber-1)*size).Take(size).ToListAsync();CanAdd=await permissions.HasAsync(User,ScreenCatalog.Units,PermissionAction.Add);CanUpdate=await permissions.HasAsync(User,ScreenCatalog.Units,PermissionAction.Update);CanDelete=await permissions.HasAsync(User,ScreenCatalog.Units,PermissionAction.Delete);}
 public async Task<IActionResult> OnPostDeleteAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.Units,PermissionAction.Delete))return Forbid();if(await db.Materials.AnyAsync(x=>x.UnitOfMeasureId==id)){TempData["Error"]="لا يمكن حذف وحدة مستخدمة في الخامات.";return RedirectToPage();}var x=await db.Units.SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();x.IsDeleted=true;x.DeletedAt=DateTimeOffset.UtcNow;x.DeletedBy=User.Identity?.Name;await db.SaveChangesAsync();return RedirectToPage();}
}
